import type {IndexCopilotSpace} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {getCopilotSpacePath} from '@github-ui/copilot-chat/utils/custom-copilots-helpers'
import {CreateSpaceDialog} from '@github-ui/copilot-spaces/components/CreateSpaceDialog'
import {ReportSpaceDialog} from '@github-ui/copilot-spaces/components/ReportSpaceDialog'
import {useFetchCopilotSpace, useFetchMenuActions, useReportUrl} from '@github-ui/copilot-spaces/hooks'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useNavigate} from '@github-ui/use-navigate'
import {CopyIcon, KebabHorizontalIcon, PencilIcon, ReportIcon, ShareIcon, TrashIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, ConfirmationDialog, IconButton, Spinner} from '@primer/react'
import {useMemo, useRef, useState} from 'react'
import {flushSync} from 'react-dom'

import {SpaceSharingDialog} from './SpaceSharingDialog'

interface CopilotSpaceMenuProps {
  onDelete: () => Promise<void>
  copilot: IndexCopilotSpace
}

export function CopilotSpacesMenu({onDelete, copilot}: CopilotSpaceMenuProps) {
  const [visibleDialog, setVisibleDialog] = useState<'delete' | 'share' | 'duplicate' | 'report' | null>(null)
  const [loading, setLoading] = useState(false)
  const [menuOpen, setMenuOpen] = useState(false)
  const [shouldFetchMenuActions, setShouldFetchMenuActions] = useState(false)
  const anchorRef = useRef<HTMLButtonElement>(null)
  const navigate = useNavigate()

  // Only fetch the full space when the duplicate dialog is visible
  const shouldFetchSpace = visibleDialog === 'duplicate'
  const {data: fullCopilotSpace, isLoading: isLoadingFullSpace} = useFetchCopilotSpace(
    shouldFetchSpace ? copilot : null,
  )

  // Fetch menu actions only after the user has clicked to open the menu
  const {
    data: menuActions,
    isLoading: isLoadingMenuActions,
    error: menuActionsError,
  } = useFetchMenuActions(shouldFetchMenuActions ? copilot.owner : '', shouldFetchMenuActions ? copilot.id : -1)

  // Extract permission fields from menuActions
  const permissions = useMemo(() => {
    if (menuActions) {
      return {
        editable: menuActions.editable,
        adminable: menuActions.adminable,
        shareable: menuActions.shareable,
        reportable: menuActions.reportable,
        // Always use copilot data for these fields
        ownerIsOrg: copilot.ownerIsOrg,
      }
    }
    // Fallback to copilot data during initial render before API call completes
    return {
      editable: copilot.editable,
      adminable: copilot.adminable,
      shareable: copilot.shareable,
      reportable: false,
      ownerIsOrg: copilot.ownerIsOrg,
    }
  }, [menuActions, copilot])

  const {editable, adminable, shareable, ownerIsOrg, reportable} = permissions

  const sharingEnabled = shareable

  const reportUrl = useReportUrl(copilot ? {id: copilot.id, owner: copilot.owner} : null)

  // Close the menu when space finishes loading when user has clicked
  // "Duplicate". We only need this for the "duplicate" dialog because it
  // requires loading the full copilot space. While it is loading we show a
  // spinner in the menu.
  const shouldAutoCloseMenu = visibleDialog === 'duplicate' && menuOpen && !isLoadingFullSpace && fullCopilotSpace
  if (shouldAutoCloseMenu) {
    setMenuOpen(false)
  }

  const closeDialog = () => {
    // eslint-disable-next-line @eslint-react/dom/no-flush-sync
    flushSync(() => setVisibleDialog(null))
    anchorRef.current?.focus()
  }

  const closeConversationSharingDialog = () => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_SHARE_DIALOG_CLOSE', mode: 'immersive'})
    closeDialog()
  }

  const applyUpdate = async (update: () => Promise<void>) => {
    closeDialog()
    setLoading(true)
    await update()
    setLoading(false)
  }

  const confirmDelete = async () => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_LIST_ACTION_DELETE', mode: 'immersive'})
    await applyUpdate(onDelete)
  }

  const onShareSpace = () => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_CONTEXT_MENU_SHARE', mode: 'immersive'})
    setVisibleDialog('share')
  }

  const onOpenDuplicateSpace = (event: Event) => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_CONTEXT_MENU_DUPLICATE', mode: 'immersive'})
    setVisibleDialog('duplicate')
    event.preventDefault()
  }

  const onReportContent = () => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_CONTEXT_MENU_REPORT', mode: 'immersive'})
    setVisibleDialog('report')
  }

  return (
    <>
      {/* Needs to manually handle open/close so that the menu can stay open
      when the user clicks 'Duplicate' and the spinner is shown until the space
      is loaded */}
      <ActionMenu
        anchorRef={anchorRef}
        open={menuOpen}
        onOpenChange={open => {
          setMenuOpen(open)
          if (open) {
            setShouldFetchMenuActions(true)
          }
        }}
      >
        <ActionMenu.Anchor>
          <IconButton
            loading={loading}
            icon={KebabHorizontalIcon}
            aria-label="Manage space"
            variant="invisible"
            onClick={() => sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_CONTEXT_MENU', mode: 'immersive'})}
          />
        </ActionMenu.Anchor>
        <ActionMenu.Overlay side="outside-bottom" align="end">
          {isLoadingMenuActions ? (
            <ActionList>
              <ActionList.Item>
                <Spinner size="small" />
              </ActionList.Item>
            </ActionList>
          ) : menuActionsError ? (
            <ActionList>
              <ActionList.Item disabled>Failed to load menu options</ActionList.Item>
            </ActionList>
          ) : (
            <ActionList>
              {editable && (
                <ActionList.Item
                  onSelect={() => {
                    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_CONTEXT_MENU_EDIT', mode: 'immersive'})
                    void navigate(getCopilotSpacePath(copilot))
                  }}
                >
                  <ActionList.LeadingVisual>
                    <PencilIcon />
                  </ActionList.LeadingVisual>
                  Edit
                </ActionList.Item>
              )}
              {sharingEnabled && (
                <ActionList.Item onSelect={onShareSpace}>
                  <ActionList.LeadingVisual>
                    <ShareIcon />
                  </ActionList.LeadingVisual>
                  Share
                </ActionList.Item>
              )}
              {(adminable || editable) && (
                <ActionList.Item
                  onSelect={e => {
                    onOpenDuplicateSpace(e as unknown as Event)
                  }}
                  // Show the loading indicator if the full space is still being
                  // loaded and the user has clicked this button to open the
                  // duplicate dialog. That way we don't show the spinner if the
                  // user hasn't tried to open the dialog yet.
                  loading={isLoadingFullSpace && visibleDialog === 'duplicate'}
                >
                  <ActionList.LeadingVisual>
                    <CopyIcon />
                  </ActionList.LeadingVisual>
                  Duplicate
                </ActionList.Item>
              )}
              {reportable && (
                <ActionList.Item onSelect={onReportContent}>
                  <ActionList.LeadingVisual>
                    <ReportIcon />
                  </ActionList.LeadingVisual>
                  Report content
                </ActionList.Item>
              )}
              {adminable && (
                <ActionList.Item
                  variant="danger"
                  onSelect={() => {
                    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_CONTEXT_MENU_DELETE', mode: 'immersive'})
                    setVisibleDialog('delete')
                  }}
                >
                  <ActionList.LeadingVisual>
                    <TrashIcon />
                  </ActionList.LeadingVisual>
                  Delete
                </ActionList.Item>
              )}
            </ActionList>
          )}
        </ActionMenu.Overlay>
      </ActionMenu>

      {visibleDialog === 'delete' ? (
        <DeleteDialog onCancel={closeDialog} onConfirm={confirmDelete} returnFocusRef={anchorRef} />
      ) : null}
      {visibleDialog === 'share' ? (
        <SpaceSharingDialog
          closeDialog={closeConversationSharingDialog}
          customCopilotId={copilot}
          userOwned={!ownerIsOrg}
        />
      ) : null}
      {visibleDialog === 'duplicate' && fullCopilotSpace ? (
        <CreateSpaceDialog
          dialogTitle="Duplicate Space"
          closeDialog={() => {
            sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_DUPLICATE_DIALOG_CLOSE', mode: 'immersive'})
            setVisibleDialog(null)
          }}
          initialSpace={fullCopilotSpace}
          returnFocusRef={anchorRef}
        />
      ) : null}
      {visibleDialog === 'report' && copilot && reportUrl ? (
        <ReportSpaceDialog
          reportUrl={reportUrl}
          onClose={() => {
            sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_REPORT_DIALOG_CLOSE', mode: 'immersive'})
            setVisibleDialog(null)
          }}
          returnFocusRef={anchorRef}
        />
      ) : null}
    </>
  )
}

interface DeleteDialogProps {
  onCancel: () => void
  onConfirm: () => Promise<void>
  returnFocusRef?: React.RefObject<HTMLElement | null> | null
}

export const DeleteDialog = ({onConfirm, onCancel, returnFocusRef}: DeleteDialogProps) => {
  const [loading, setLoading] = useState(false)

  const handleConfirm = async () => {
    setLoading(true)
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_DIALOG_DELETE_CONFIRM', mode: 'immersive'})
    try {
      await onConfirm()
    } finally {
      setLoading(false)
    }
  }

  const handleCancel = () => {
    sendEvent('dotcom_chat.activate', {target: 'COPILOT_SPACE_DIALOG_DELETE_CANCEL', mode: 'immersive'})
    onCancel()
    // Return focus to the button that opened the dialog. Needs setTimeout or ref will not be focused correctly.
    setTimeout(() => returnFocusRef?.current?.focus(), 0)
  }

  return (
    <ConfirmationDialog
      title="Delete space"
      onClose={async gesture => {
        if (loading) {
          return
        } else if (gesture === 'confirm') {
          await handleConfirm()
        } else {
          handleCancel()
        }
      }}
      confirmButtonContent={loading ? <Spinner size="small" /> : 'Delete'}
      confirmButtonType="danger"
    >
      Are you sure you want to delete this space? This action cannot be undone.
    </ConfirmationDialog>
  )
}
