import {useEffect} from 'react'

import {useChatStateValues} from '../../../utils/CopilotChatContext'
import {useTraceManager} from '../TraceManagerContext'

/** Monitor the selected thread and ensure we load the trace for it */
export function useAutoLoadTrace() {
  const traceManager = useTraceManager()
  const {selectedThreadID, fetchSharedThreads} = useChatStateValues('selectedThreadID', 'fetchSharedThreads')

  // Detect if we're viewing a a shared thread by checking if there's shared thread data
  // Also make sure we are not on a duplicated thread by comparing the selectedThreadID to the shareId
  const isSharedThread = !!fetchSharedThreads?.shareId && selectedThreadID === fetchSharedThreads?.shareId

  // Load traces when selected thread changes (for regular threads)
  useEffect(() => {
    if (!selectedThreadID || isSharedThread) return

    void traceManager.fetchAndLoadTraces(selectedThreadID)
  }, [selectedThreadID, traceManager, isSharedThread])

  // Load traces when shared thread messages are fetched successfully
  useEffect(() => {
    if (!fetchSharedThreads?.ok || !fetchSharedThreads.originalThreadId || !isSharedThread || !selectedThreadID) return

    void traceManager.fetchAndLoadTraces(fetchSharedThreads.originalThreadId, selectedThreadID)
  }, [fetchSharedThreads, traceManager, isSharedThread, selectedThreadID])
}
