import {CopilotNavigationWithContext} from '@github-ui/copilot-chat/components/navigation/CopilotNavigation'
import {copilotFeatureFlags} from '@github-ui/copilot-chat/utils/copilot-feature-flags'
import {Layout as PacerLayout} from '@github-ui/pacer/Layout'
import {Outlet} from '@github-ui/react-router'

import {SpacesHeader} from '../components/Spaces/SpacesHeader'
import {COPILOT_FAVICON} from '../utils/constants'

/**
 * Pathless layout route for all /copilot/spaces/* routes.
 *
 * Provides the shared PacerLayout shell (SpacesHeader + sidebar) and renders
 * <Outlet /> in the content area for the matched child (SpacesListView or
 * SpacesConversationView).
 */
export function SpacesLayout() {
  return (
    <PacerLayout
      data-testid="chat-layout"
      data-hpc
      faviconOverride={COPILOT_FAVICON}
      slimLineTopTabs={copilotFeatureFlags.copilotWorkbenchSlimLineTopTabs}
    >
      <PacerLayout.Header>
        <SpacesHeader />
      </PacerLayout.Header>

      <PacerLayout.Sidebar>
        <CopilotNavigationWithContext />
      </PacerLayout.Sidebar>

      <PacerLayout.ColumnLeft>
        <Outlet />
      </PacerLayout.ColumnLeft>
    </PacerLayout>
  )
}
