import type {CopilotChatRepo} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {sendRefTelemetry} from '@github-ui/copilot-chat/utils/custom-copilots-helpers'
import {MultiFilePicker} from '@github-ui/copilot-spaces/components/MultiFilePicker'
import type {CopilotSpaceResource, GitHubFileFormData, ResourceCounts} from '@github-ui/copilot-spaces/types'
/* eslint-disable-next-line @github-ui/github-monorepo/no-use-app-payload --
   useAppPayload is deprecated. See
   https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
import {useAppPayload} from '@github-ui/react-core/use-app-payload'
import {useRef} from 'react'

import type {CopilotImmersivePayload} from '../../routes/payloads'
import {useGetCopilotSpaceResourceSizes} from './hooks/use-get-copilot-space-resource-sizes'

interface SpacesFilePickerProps {
  isOpen: boolean
  onClose: () => void
  onResourcesAdded: (resources: CopilotSpaceResource[]) => void
  owner?: string
  resourceCounts?: ResourceCounts
  initialRepo?: CopilotChatRepo | null
  onRepoSelect?: (repo: CopilotChatRepo | null) => void
  // Whether to hide the back button in the dialog header of the file picker.
  hideBackButton?: boolean
}

export function SpacesFilePicker({
  isOpen,
  onClose,
  onResourcesAdded,
  owner,
  resourceCounts,
  initialRepo,
  onRepoSelect,
  hideBackButton,
}: SpacesFilePickerProps) {
  const attachmentButtonRef = useRef<HTMLButtonElement>(null)
  const {getCopilotSpaceResourceSizes: validateCopilotSpaceResource} = useGetCopilotSpaceResourceSizes()

  const {searchWorkerFilePath} = useAppPayload<CopilotImmersivePayload>()

  const saveGitHubResources = async (data: GitHubFileFormData[]) => {
    const resources = data.filter(
      (item): item is GitHubFileFormData & {type: 'github_file'} => item.type === 'github_file',
    )

    if (resources.length === 0) {
      onClose()
      return
    }

    const validationResult = await validateCopilotSpaceResource({
      resources: resources as CopilotSpaceResource[],
    })
    const hydratedResources = resources.map(resource => {
      const resourceId = resource.id
      const fileSizePercentage = validationResult[resourceId]
      return {
        ...resource,
        fileExists: true,
        markedForDestroy: false,
        sizePercentage: fileSizePercentage,
      }
    })
    onResourcesAdded(hydratedResources)
    sendRefTelemetry(hydratedResources, 'file-picker')
    onClose()
  }

  if (!isOpen) {
    return null
  }

  return (
    <MultiFilePicker
      formData={[]}
      onCancel={onClose}
      onSaveFiles={saveGitHubResources}
      findFileWorkerPath={searchWorkerFilePath}
      attachmentButtonRef={attachmentButtonRef}
      owner={owner}
      resourceCounts={resourceCounts}
      initialRepo={initialRepo}
      onRepoSelect={onRepoSelect}
      hideBackButton={hideBackButton}
      maxFileCount={50}
    />
  )
}
