import {LAYOUT_BREAKPOINT} from '@github-ui/pacer/Layout'
import {useEffect, useState} from 'react'

/**
 * hook for tracking media state
 * @param query - the media query string to match
 * @returns boolean indicating if the media query matches
 */
function useMediaQuery(query: string): boolean {
  const [matches, setMatches] = useState(() => {
    if (typeof window === 'undefined') return false
    return window.matchMedia(query).matches
  })

  useEffect(() => {
    const mediaQuery = window.matchMedia(query)

    const handleChange = (event: MediaQueryListEvent) => {
      setMatches(event.matches)
    }

    // eslint-disable-next-line react-hooks/set-state-in-effect
    setMatches(mediaQuery.matches)
    mediaQuery.addEventListener('change', handleChange)

    return () => {
      mediaQuery.removeEventListener('change', handleChange)
    }
  }, [query])

  return matches
}

export interface ViewportBreakpointState {
  /** whether the viewport is narrow (below 1024px) */
  isNarrowViewport: boolean
  // future possibilities, if we ever feel like these are needed:
  //   - whether content preview should auto-open (not on narrow viewports)
  //   - whether content preview panel should be shown at all */
}

/**
 * detects the viewport breakpoint, and uses the layout breakpoint (1024px) by default to determine viewport size.
 *
 * @param breakpoint - the media query string to use (defaults to LAYOUT_BREAKPOINT)
 * - on narrow viewports (< 1024px): mobile/tablet experience
 * - on wide viewports (>= 1024px): desktop experience
 */
export function useViewportBreakpoint(breakpoint: string = LAYOUT_BREAKPOINT): ViewportBreakpointState {
  const isNarrowViewport = useMediaQuery(breakpoint)

  return {
    isNarrowViewport,
  }
}
